import ast

def is_valid_expression(expr: str) -> bool:
    try:
        tree = ast.parse(expr, mode='eval')
        return isinstance(tree, ast.Expression)
    except SyntaxError:
        return False

# Test the function with a valid and an invalid expression
print(is_valid_expression("2 + 3 * 5"))  # Expected: True
print(is_valid_expression("2 + (3 *"))   # Expected: False

import ast

def test_ast_parsing(expr):
    try:
        tree = ast.parse(expr, mode='eval')
        print("Parsed successfully:", ast.dump(tree))
    except SyntaxError as e:
        print("SyntaxError:", e)

# Test with a complex expression
test_ast_parsing("1 + 2 * (3 / (4 - 5)) ** 6")

